/* Hypr Studio (LabtosoStudios) – automatisch erzeugt, wird beim Anwenden überschrieben */
configuration {
    modi: "drun,run,window";
    show-icons: true;
    font: "JetBrainsMono Nerd Font 12";
    terminal: "kitty";
    display-drun: "Apps";
    display-run: "Apps";
    display-window: "Apps";
    drun-display-format: "{name}";
    matching: "prefix";
    tokenize: false;
    drun-match-fields: "name";
    sorting-method: "fzf";
    case-sensitive: false;
    sort: true;
    hover-select: true;
}

@theme "/H/.config/rofi/hyprstudio.rasi"

/* Hypr Studio (LabtosoStudios) – automatisch erzeugt, wird beim Anwenden überschrieben */
* {
    bg:      #1a1b26f0;
    fg:      #c0caf5ff;
    accent:  #7aa2f7ff;
    sel:     #7aa2f733;
    sel-fg:  #ffffffff;
    input:   #24283bff;
    bordercol: #7aa2f7ff;
    muted:   #c0caf588;
    background-color: transparent;
    text-color: @fg;
}

window {
    location: center;
    anchor: center;
    y-offset: 0px;
    width: 620px;
    background-color: @bg;
    border: 2px solid;
    border-color: @bordercol;
    border-radius: 14px;
    padding: 16px;
}

mainbox {
    spacing: 12px;
    children: [ inputbar, listview ];
}

inputbar {
    children: [ prompt, entry ];
    spacing: 10px;
    padding: 10px 14px;
    border-radius: 10px;
    background-color: @input;
}

prompt {
    text-color: @accent;
}

entry {
    placeholder: "Suchen …";
    placeholder-color: @muted;
    cursor: text;
}

listview {
    lines: 8;
    columns: 1;
    spacing: 4px;
    fixed-height: true;
    scrollbar: false;
}

scrollbar {
    handle-color: @accent;
    handle-width: 4px;
    border-radius: 4px;
}

element {
    orientation: horizontal;
    padding: 8px 10px;
    spacing: 12px;
    border-radius: 8px;
}

element selected.normal, element selected.active {
    background-color: @sel;
    text-color: @sel-fg;
}

element-icon {
    size: 24px;

}

element-text {
    vertical-align: 0.5;

    text-color: inherit;
}

/* Hypr Studio (LabtosoStudios) – automatisch erzeugt, wird beim Anwenden überschrieben */
* {
    font-family: "JetBrainsMono Nerd Font", sans-serif;
    font-size: 14px;
}

window {
    margin: 0;
    border: 2px solid rgba(122, 162, 247, 1.00);
    border-radius: 14px;
    background-color: rgba(26, 27, 38, 0.94);
}

#outer-box {
    padding: 16px;
}

#input {
    margin-bottom: 12px;
    padding: 10px 14px;
    border: none;
    border-radius: 10px;
    background-color: rgba(36, 40, 59, 1.00);
    color: rgba(192, 202, 245, 1.00);
    box-shadow: none;
    outline: none;
}

#inner-box, #scroll {
    background: transparent;
}

#entry {
    padding: 8px 10px;
    margin: 2px 0;
    border-radius: 8px;
}

#entry:selected {
    background-color: rgba(122, 162, 247, 0.20);
    outline: none;
}

#text {
    color: rgba(192, 202, 245, 1.00);
    margin-left: 10px;
}

#entry:selected #text {
    color: rgba(255, 255, 255, 1.00);
}

/* Hypr Studio (LabtosoStudios) – generated, overwritten when applied */
* { all: unset; font-family: "JetBrainsMono Nerd Font"; font-size: 12pt; }
scrollbar { opacity: 0; }
.normal-icons { -gtk-icon-size: 24px; }
.large-icons { -gtk-icon-size: 32px; }
.box-wrapper { background: rgba(26,27,38,0.94); padding: 16px; border-radius: 14px;
  border: 2px solid rgba(122,162,247,1.00); min-width: 620px; }
.input { caret-color: rgba(122,162,247,1.00); background: rgba(36,40,59,1.00); padding: 10px;
  color: rgba(192,202,245,1.00); border-radius: 8px; }
.input placeholder { opacity: 0.5; }
.list { color: rgba(192,202,245,1.00); }
.item-box { border-radius: 8px; padding: 10px; }
child:selected .item-box, row:selected .item-box { background: rgba(122,162,247,0.20); color: rgba(255,255,255,1.00); }
.item-subtext { font-size: 10pt; opacity: 0.55; }
.keybinds { padding-top: 8px; font-size: 10pt; color: rgba(192,202,245,1.00); opacity: 0.6; }
.preview { border: 1px solid rgba(122,162,247,1.00); border-radius: 8px; color: rgba(192,202,245,1.00); }

