* {
    font-family: "JetBrainsMono Nerd Font", sans-serif;
    font-size: 14px;
}

window {
    margin: 0;
    border: 2px solid rgba(230, 237, 245, 1.00);
    border-radius: 0px;
    background-color: rgba(14, 19, 26, 0.93);
}

#outer-box {
    padding: 16px;
}

#input {
    margin-bottom: 12px;
    padding: 10px 14px;
    border: none;
    border-radius: 0px;
    background-color: rgba(27, 36, 48, 1.00);
    color: rgba(230, 237, 245, 1.00);
    box-shadow: none;
    outline: none;
}

#inner-box, #scroll {
    background: transparent;
}

#entry {
    padding: 8px 10px;
    margin: 2px 0;
    border-radius: 0px;
}

#entry:selected {
    background-color: rgba(230, 237, 245, 0.20);
    outline: none;
}

#text {
    color: rgba(230, 237, 245, 1.00);
    margin-left: 10px;
}

#entry:selected #text {
    color: rgba(255, 255, 255, 1.00);
}

