    margin-left: 10px;
}

#entry:selected #text {
    color: rgba(255, 255, 255, 1.00);
}

/* Hypr Studio (LabtosoStudios) – generated, overwritten when applied */
* { all: unset; font-family: "JetBrainsMono Nerd Font"; font-size: 12pt; }
scrollbar { opacity: 0; }
.normal-icons { -gtk-icon-size: 24px; }
.large-icons { -gtk-icon-size: 32px; }
.box-wrapper { background: rgba(46,52,64,1.00); padding: 16px; border-radius: 8px;
  border: 2px solid rgba(76,86,106,1.00); min-width: 620px; }
.input { caret-color: rgba(136,192,208,1.00); background: rgba(59,66,82,1.00); padding: 10px;
  color: rgba(236,239,244,1.00); border-radius: 8px; }
.input placeholder { opacity: 0.5; }
.list { color: rgba(236,239,244,1.00); }
.item-box { border-radius: 8px; padding: 10px; }
child:selected .item-box, row:selected .item-box { background: rgba(136,192,208,0.20); color: rgba(255,255,255,1.00); }
.item-subtext { font-size: 10pt; opacity: 0.55; }
.keybinds { padding-top: 8px; font-size: 10pt; color: rgba(236,239,244,1.00); opacity: 0.6; }
.preview { border: 1px solid rgba(76,86,106,1.00); border-radius: 8px; color: rgba(236,239,244,1.00); }

